<?php
/** Own PF fictional site: native contact form → validated lead in local WordPress; no email. */
defined('ABSPATH')||exit;
add_action('init',function(){register_post_type('pf_demo_lead',['labels'=>['name'=>'Zgłoszenia demonstracyjne','singular_name'=>'Zgłoszenie'],'public'=>false,'show_ui'=>true,'show_in_menu'=>true,'menu_icon'=>'dashicons-email-alt','supports'=>['title','editor','custom-fields'],'capability_type'=>'post']);});
add_filter('use_block_editor_for_post',function($use,$post){return $post&&get_post_meta($post->ID,'_pf_own_fiction',true)?false:$use;},20,2);
add_shortcode('pf_contact_form',function(){
 $action=admin_url('admin-post.php');$nonce=wp_create_nonce('pf_own_contact');
 return '<form class="pf-form" action="'.esc_url($action).'" method="post"><input type="hidden" name="action" value="pf_own_contact"><input type="hidden" name="pf_nonce" value="'.esc_attr($nonce).'"><label for="pf-name">Imię</label><input id="pf-name" name="pf_name" autocomplete="given-name" maxlength="80" required><label for="pf-contact">E-mail lub telefon do kontaktu</label><input id="pf-contact" name="pf_contact" autocomplete="email" maxlength="120" required><label for="pf-message">Czego dotyczy kontakt?</label><textarea id="pf-message" name="pf_message" maxlength="1500" required></textarea><div class="pf-hp" aria-hidden="true"><label>Nie wypełniaj<input name="pf_company_url" tabindex="-1" autocomplete="off"></label></div><label class="consent"><input type="checkbox" name="pf_consent" value="1" required><span>Zgadzam się na kontakt dotyczący wiadomości. To własny lokalny test — nie podawaj danych wrażliwych. Żaden e-mail nie zostanie wysłany.</span></label><button class="pf-button" type="submit">Zapisz zgłoszenie demonstracyjne</button></form>';
});
function pf_own_contact_handle(){
 if(($_SERVER['REQUEST_METHOD']??'')!=='POST')wp_die('Metoda niedozwolona.', 'Formularz', ['response'=>405]);
 if(empty($_POST['pf_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['pf_nonce'])),'pf_own_contact'))wp_die('Nieprawidłowy token formularza. Odśwież stronę.', 'Formularz', ['response'=>403]);
 $name=sanitize_text_field(wp_unslash($_POST['pf_name']??''));$contact=sanitize_text_field(wp_unslash($_POST['pf_contact']??''));$message=sanitize_textarea_field(wp_unslash($_POST['pf_message']??''));
 $contact_ok=str_contains($contact,'@')?is_email($contact):(bool)preg_match('/^\+?[0-9 ()-]{7,20}$/',$contact);
 if(!empty($_POST['pf_company_url'])||!$name||mb_strlen($name)>80||!$contact_ok||!$message||mb_strlen($message)>1500||($_POST['pf_consent']??'')!=='1')wp_die('Sprawdź wymagane dane i zgodę na kontakt.', 'Formularz', ['response'=>422]);
 $key='pf_demo_rate_'.hash('sha256',$_SERVER['REMOTE_ADDR']??'local');$n=(int)get_transient($key);if($n>=3)wp_die('Limit demonstracyjnych zgłoszeń. Spróbuj później.', 'Formularz', ['response'=>429]);
 $id=wp_insert_post(['post_type'=>'pf_demo_lead','post_status'=>'private','post_title'=>'Własny test / '.$name,'post_content'=>$message],true);if(is_wp_error($id))wp_die('Nie zapisano zgłoszenia.', 'Formularz', ['response'=>500]);
 update_post_meta($id,'_pf_contact',$contact);update_post_meta($id,'_pf_consent','yes');update_post_meta($id,'_pf_notification_mode','LOCAL_CMS_ONLY_NO_EMAIL');update_post_meta($id,'_pf_source','own-fictional-demo');set_transient($key,$n+1,HOUR_IN_SECONDS);
 // Deliberately no wp_mail, SMTP, third-party hook or remote request.
 wp_safe_redirect(home_url('/dziekujemy/?demo=recorded'),303);exit;
}
add_action('admin_post_nopriv_pf_own_contact','pf_own_contact_handle');add_action('admin_post_pf_own_contact','pf_own_contact_handle');
function pf_google_embed_allowed($url){$host=wp_parse_url($url,PHP_URL_HOST);$path=wp_parse_url($url,PHP_URL_PATH);return wp_parse_url($url,PHP_URL_SCHEME)==='https'&&in_array($host,['www.google.com','maps.google.com'],true)&&str_starts_with($path??'','/maps/embed');}
add_shortcode('pf_google_reviews',function(){
 $url=(string)get_option('pf_own_google_embed','');
 if(!$url||!pf_google_embed_allowed($url))return '<aside class="pf-review-note"><h3>Moduł opinii Google</h3><p>Własna fikcyjna kancelaria nie ma profilu Google ani prawdziwych opinii. Nie wymyślamy ocen. W projekcie klienta ten moduł otrzyma zatwierdzony kod widżetu lub dane uprawnionego profilu; dostawcę i dostęp uzgadniamy przed finansowaniem.</p><p>Próbka potwierdza moduł konfiguracji, walidację adresu i miejsce integracji. Nie potwierdza odczytu Google API.</p></aside>';
 return '<section aria-label="Widget profilu Google"><iframe title="Widżet profilu Google dostarczony przez właściciela" src="'.esc_url($url).'" width="100%" height="380" loading="lazy" referrerpolicy="no-referrer-when-downgrade" style="border:0"></iframe></section>';
});
add_action('wp_head',function(){if(is_singular()&&get_post_meta(get_queried_object_id(),'_pf_own_fiction',true))echo '<meta name="description" content="'.esc_attr(get_post_meta(get_queried_object_id(),'_pf_seo_description',true)).'">';});
add_filter('pre_get_document_title',function($title){$id=get_queried_object_id();return is_singular()&&get_post_meta($id,'_pf_own_fiction',true)?get_post_meta($id,'_pf_seo_title',true):$title;});
add_action('add_meta_boxes_page',function($post){if(!get_post_meta($post->ID,'_pf_own_fiction',true))return;add_meta_box('pf-native-seo','Ustawienia własnej strony PF',function($post){wp_nonce_field('pf_seo_'.$post->ID,'pf_seo_nonce');echo '<p>Własny fikcyjny przykład; treść edytujesz w natywnym Classic/TinyMCE.</p><p><label>Tytuł SEO<input class="widefat" name="pf_seo_title" value="'.esc_attr(get_post_meta($post->ID,'_pf_seo_title',true)).'"></label></p><p><label>Opis SEO<textarea class="widefat" rows="3" name="pf_seo_description">'.esc_textarea(get_post_meta($post->ID,'_pf_seo_description',true)).'</textarea></label></p>';if($post->ID===(int)get_option('page_on_front'))echo '<p><label>Adres uprawnionego widżetu Google (opcjonalny w demonstracji)<input class="widefat" type="url" name="pf_google_embed" value="'.esc_attr(get_option('pf_own_google_embed','')).'"></label></p><p>Bez adresu pokazujemy uczciwe oznaczenie braku opinii. To nie jest dowód połączenia z Google API.</p>';},'page','normal','high');});
add_action('save_post_page',function($id){if(!get_post_meta($id,'_pf_own_fiction',true)||wp_is_post_revision($id)||(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE)||!current_user_can('edit_post',$id)||empty($_POST['pf_seo_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['pf_seo_nonce'])),'pf_seo_'.$id))return;foreach(['title','description'] as $k)if(isset($_POST['pf_seo_'.$k]))update_post_meta($id,'_pf_seo_'.$k,sanitize_text_field(wp_unslash($_POST['pf_seo_'.$k])));if($id===(int)get_option('page_on_front')&&isset($_POST['pf_google_embed'])){$url=esc_url_raw(wp_unslash($_POST['pf_google_embed']));if(!$url||pf_google_embed_allowed($url))update_option('pf_own_google_embed',$url);}});
